CREATE TABLE administradores (id_admin INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(80) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE aspirantes (id_aspirante INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(80) NOT NULL,apellidos VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,telefono VARCHAR(20),ciudad VARCHAR(80),colegio VARCHAR(120),creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE universidades (id_universidad INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(160) NOT NULL,ciudad VARCHAR(80) NOT NULL,departamento VARCHAR(80) NOT NULL,tipo ENUM('publica','privada') NOT NULL,sitio_web VARCHAR(255),email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE programas (id_programa INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(140) NOT NULL,modalidad VARCHAR(40) NOT NULL,duracion TINYINT UNSIGNED NOT NULL,id_universidad INT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_programa_universidad FOREIGN KEY(id_universidad) REFERENCES universidades(id_universidad) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE beneficios (id_beneficio INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,descripcion VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE universidad_beneficios (id_universidad INT NOT NULL,id_beneficio INT NOT NULL,PRIMARY KEY(id_universidad,id_beneficio),FOREIGN KEY(id_universidad) REFERENCES universidades(id_universidad) ON DELETE CASCADE,FOREIGN KEY(id_beneficio) REFERENCES beneficios(id_beneficio) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE intereses (id_interes INT AUTO_INCREMENT PRIMARY KEY,id_aspirante INT NOT NULL,id_programa INT NOT NULL,fecha DATE NOT NULL,UNIQUE KEY uq_interes(id_aspirante,id_programa),FOREIGN KEY(id_aspirante) REFERENCES aspirantes(id_aspirante) ON DELETE CASCADE,FOREIGN KEY(id_programa) REFERENCES programas(id_programa) ON DELETE CASCADE) ENGINE=InnoDB;
